from app.core.resources import CATALOG, display_rows, validate_record

"""Admission Enquiries endpoints and their PostgreSQL queries."""

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.core import sql_queries as sql
from app.core.resources import staff_only
from app.core.security import StrictModel, require

from .schemas import CreateRequest, UpdateRequest
from .service import Service

TABLE = "admission_enquiries"
router = APIRouter(prefix="/admission-enquiries", tags=["Admission Enquiries"])


# --- PostgreSQL queries for this screen (generated by tools/generate_module_sql.py from the
# live table definitions; regenerate after schema migrations). Values are bound as %(name)s
# parameters, never formatted into the text; app.core.sql_queries runs these statements and
# keeps custom fields (record_extras) with each record. Table names resolve through the
# connection's search_path (EDUNEXA_DB_SCHEMA).

LIST_SQL = """
SELECT t.code,
       t.campus_code,
       t.source_code,
       t.cycle_code,
       t.program_code,
       t.first_name,
       t.last_name,
       t.phone,
       t.email,
       t.parent_name,
       t.parent_phone,
       t.referrer_name,
       t.campaign_reference,
       t.assigned_employee_code,
       t.status,
       t.next_follow_up_at,
       t.communication_consent,
       t.consent_recorded_at,
       x.data AS extras
FROM admission_enquiries AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'admission_enquiries' AND x.record_code = t.code
ORDER BY t.code
"""

GET_SQL = """
SELECT t.code,
       t.campus_code,
       t.source_code,
       t.cycle_code,
       t.program_code,
       t.first_name,
       t.last_name,
       t.phone,
       t.email,
       t.parent_name,
       t.parent_phone,
       t.referrer_name,
       t.campaign_reference,
       t.assigned_employee_code,
       t.status,
       t.next_follow_up_at,
       t.communication_consent,
       t.consent_recorded_at,
       x.data AS extras
FROM admission_enquiries AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'admission_enquiries' AND x.record_code = t.code
WHERE t.code = %(code)s
"""

INSERT_SQL = """
INSERT INTO admission_enquiries (
    code,
    campus_code,
    source_code,
    cycle_code,
    program_code,
    first_name,
    last_name,
    phone,
    email,
    parent_name,
    parent_phone,
    referrer_name,
    campaign_reference,
    assigned_employee_code,
    status,
    next_follow_up_at,
    communication_consent,
    consent_recorded_at
)
VALUES (
    %(code)s,
    %(campus_code)s,
    %(source_code)s,
    %(cycle_code)s,
    %(program_code)s,
    %(first_name)s,
    %(last_name)s,
    %(phone)s,
    %(email)s,
    %(parent_name)s,
    %(parent_phone)s,
    %(referrer_name)s,
    %(campaign_reference)s,
    %(assigned_employee_code)s,
    COALESCE(%(status)s, 'new'::text),
    %(next_follow_up_at)s,
    COALESCE(%(communication_consent)s, false),
    %(consent_recorded_at)s
)
"""

UPDATE_SQL = """
UPDATE admission_enquiries
SET campus_code = %(campus_code)s,
    source_code = %(source_code)s,
    cycle_code = %(cycle_code)s,
    program_code = %(program_code)s,
    first_name = %(first_name)s,
    last_name = %(last_name)s,
    phone = %(phone)s,
    email = %(email)s,
    parent_name = %(parent_name)s,
    parent_phone = %(parent_phone)s,
    referrer_name = %(referrer_name)s,
    campaign_reference = %(campaign_reference)s,
    assigned_employee_code = %(assigned_employee_code)s,
    status = %(status)s,
    next_follow_up_at = %(next_follow_up_at)s,
    communication_consent = %(communication_consent)s,
    consent_recorded_at = %(consent_recorded_at)s
WHERE code = %(code)s
"""

DELETE_SQL = """
DELETE FROM admission_enquiries
WHERE code = %(code)s
"""

REFERENCED_BY_SQL = """
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM admission_applications WHERE enquiry_code = %(code)s) THEN 'admission_applications'
    WHEN EXISTS (SELECT 1 FROM enquiry_followups WHERE enquiry_code = %(code)s) THEN 'enquiry_followups'
END AS referenced_by
"""
# --- end of generated SQL


def query_list(data):
    return sql.fetch_all(data, TABLE, LIST_SQL)


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


class IntakeInput(StrictModel):
    values: dict


@router.post("/intake", status_code=201)
def create_intake(body: IntakeInput, request: Request, user=Depends(require(TABLE, "create"))):
    """Admission screen intake: normalized enquiry fields plus approved extra details."""
    staff_only(user)
    known = {field["name"] for field in CATALOG[TABLE]["fields"]}
    values = body.values
    record_values = {key: value for key, value in values.items() if key in known}
    extras = {key: value for key, value in values.items() if key not in known}
    if record_values.get("status") == "joined":
        record_values["status"] = "closed"
        extras["workflow_status"] = "joined"
    with request.app.state.store.transaction() as data:
        if not record_values.get("source_code") or record_values["source_code"] not in data["records"].get("admission_sources", {}):
            sources = data["records"].get("admission_sources", {})
            direct = next((source for source in sources.values() if source.get("is_active") and source.get("channel") == "walk_in"), None)
            if direct is None:
                from app.modules.admissions.admission_sources.api import service as sources_service
                direct = sources_service.create(data, {"name": "Direct / walk-in", "channel": "walk_in", "is_active": True}, user["code"])
            record_values["source_code"] = direct["code"]
        record = validate_record(TABLE, record_values)
        created = service.create(data, record, user["code"])
        created.update(extras)
        query_save(data, created)
        return created


@router.patch("/intake/{code}")
def update_intake(code: str, body: IntakeInput, request: Request, user=Depends(require(TABLE, "edit"))):
    """Update enquiry workflow state and its retained intake details."""
    staff_only(user)
    known = {field["name"] for field in CATALOG[TABLE]["fields"]}
    values = body.values
    record_values = {key: value for key, value in values.items() if key in known}
    extras = {key: value for key, value in values.items() if key not in known}
    if record_values.get("status") == "joined":
        record_values["status"] = "closed"
        extras["workflow_status"] = "joined"
    elif "status" in record_values:
        extras["workflow_status"] = None
    with request.app.state.store.transaction() as data:
        updated = service.update(data, code, record_values, user["code"])
        updated.update(extras)
        query_save(data, updated)
        return updated


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = display_rows(data, TABLE, query_list(data))
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    return query_get(request.app.state.store.snapshot(), code)


@router.post("", status_code=201)
def create_record(
    body: CreateRequest, request: Request, user=Depends(require(TABLE, "create"))
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.create(
            data, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.patch("/{code}")
def update_record(
    code: str,
    body: UpdateRequest,
    request: Request,
    user=Depends(require(TABLE, "edit")),
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.update(
            data, code, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.delete("/{code}", status_code=204)
def delete_record(code: str, request: Request, user=Depends(require(TABLE, "delete"))):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        service.delete(data, code, user["code"])
